 IF EXISTS(SELECT 1 FROM rrc267_new_entries e WHERE(SELECT COUNT(*)FROM tradeskill_recipe_entries r WHERE r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)<>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC267 new logical entry multiplicity mismatch'; END IF;
 IF (SELECT COUNT(*)FROM tradeskill_recipe)<>recipes_before+257 OR(SELECT COUNT(*)FROM tradeskill_recipe_entries)<>entries_before+1715 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC267 total row-count delta mismatch'; END IF;
 DROP TEMPORARY TABLE rrc267_peer_entries;
 DROP TEMPORARY TABLE rrc267_peers;
 DROP TEMPORARY TABLE rrc267_new_entries;
 DROP TEMPORARY TABLE rrc267_new;
 DROP TEMPORARY TABLE rrc267_existing_entries;
 DROP TEMPORARY TABLE rrc267_after;
 DROP TEMPORARY TABLE rrc267_before;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT CONVERT(0x525243323637 USING utf8mb4),0,recipes_before,(SELECT COUNT(*)FROM tradeskill_recipe),entries_before,(SELECT COUNT(*)FROM tradeskill_recipe_entries),@@in_transaction;
END//
DELIMITER ;
